// ── CONFIG ── set these once in the n8n editor (stored encrypted).
const SUPABASE_URL = 'https://YOUR-PROJECT.supabase.co';
const SERVICE_KEY  = 'PASTE_SUPABASE_SERVICE_ROLE_KEY';
const THUMB_BUCKET = 'thumbnails';

const src = $json.body || $json;
const savedItemId = src.saved_item_id;
const oembedUrl   = src.oembed_url || null;
const platform    = src.platform || 'manual';
if (!savedItemId) return { json: { ok: false, error: 'missing saved_item_id' } };

const sb = (method, path, body, extraHeaders) => this.helpers.httpRequest({
  method,
  url: `${SUPABASE_URL}${path}`,
  headers: Object.assign({ apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}` }, extraHeaders || {}),
  body,
  json: body !== undefined && !(body instanceof Buffer)
});

// Need the owner id so Storage paths satisfy the owner-scoped RLS policy.
let userId = null;
try {
  const rows = await sb('GET', `/rest/v1/saved_items?id=eq.${savedItemId}&select=user_id`);
  userId = Array.isArray(rows) && rows[0] ? rows[0].user_id : null;
} catch (e) { /* non-fatal */ }

let oembed = {};
let status = 'complete';
try {
  if (oembedUrl) {
    const o = await this.helpers.httpRequest({ method: 'GET', url: oembedUrl, json: true });
    oembed = {
      title: o.title || null,
      author_name: o.author_name || null,
      author_url: o.author_url || null,
      thumbnail_url: o.thumbnail_url || null,
      provider: o.provider_name || platform,
      html: o.html || null
    };
  }
} catch (e) {
  status = 'failed';
  oembed = { fetch_error: String((e && e.message) || e) };
}

// ── Media: download the oembed thumbnail → upload to the private bucket →
// record it in saved_item_media. All best-effort; failure never fails the item.
let mediaStored = null;
try {
  if (oembed.thumbnail_url && userId) {
    const bin = await this.helpers.httpRequest({ method: 'GET', url: oembed.thumbnail_url, encoding: 'arraybuffer' });
    const path = `${userId}/${savedItemId}/thumb.jpg`;
    await sb('POST', `/storage/v1/object/${THUMB_BUCKET}/${path}`, Buffer.from(bin), {
      'Content-Type': 'image/jpeg',
      'x-upsert': 'true'
    });
    await sb('POST', '/rest/v1/saved_item_media', {
      saved_item_id: savedItemId,
      media_type: 'thumbnail',
      storage_path: `${THUMB_BUCKET}/${path}`,
      sort_order: 0
    }, { Prefer: 'return=minimal' });
    mediaStored = path;
  }
} catch (e) {
  mediaStored = { media_error: String((e && e.message) || e) };
}

// Prefer the user's shared text as the caption; fall back to the oembed title.
const patch = {
  processing_status: status,
  raw_caption: src.text || oembed.title || null,
  source_creator_handle: oembed.author_name || null,
  original_post_data: Object.assign({}, src, { oembed })
};
await sb('PATCH', `/rest/v1/saved_items?id=eq.${savedItemId}`, patch, { Prefer: 'return=minimal' });

return { json: { ok: true, saved_item_id: savedItemId, status, oembed, mediaStored } };
